    ["VU"] = "GESEHEN",
    ["vu crafter (sans l'addon)"] = "beim Herstellen gesehen (ohne Addon)",
    ["vu crafter"] = "beim Herstellen gesehen",
    ["%d+ · vu crafter"] = "%d+ · beim Herstellen gesehen",
    -- Cooldowns de recettes (transmutations & co)
    ["%s : prête"] = "%s: bereit",
    ["%s : dans %s"] = "%s: in %s",
    ["(estimé)"] = "(geschätzt)",
