    -- Rerolls (identité joueur multi-persos, /co alts — opt-in)
    ["rerolls : ACTIVÉS — ta liste de persos est annoncée au réseau."] =
        "Twinks: AKTIVIERT — deine Charakterliste wird im Netzwerk angekündigt.",
    ["rerolls : désactivés — rien n'est annoncé (opt-in : /co alts on)."] =
        "Twinks: deaktiviert — nichts wird angekündigt (Opt-in: /co alts on).",
    ["perso principal (vitrine) : %s"] = "Hauptcharakter (Aushängeschild): %s",
    ["persos du compte (%s) : %s"] = "Charaktere des Accounts (%s): %s",
    ["le lien n'est vérifié chez les autres qu'après une connexion de CHAQUE perso (addon actif)."] =
        "Andere bestätigen die Verknüpfung erst, wenn sich JEDER Charakter einmal eingeloggt hat (Addon aktiv).",
    ["rerolls activés — perso principal : %s (changer : /co alts main <nom>)"] =
        "Twinks aktiviert — Hauptcharakter: %s (ändern: /co alts main <Name>)",
    ["rerolls désactivés — dissolution annoncée au réseau."] =
        "Twinks deaktiviert — Auflösung im Netzwerk angekündigt.",
    ["perso inconnu sur ce compte : %s (connecte-le une fois avec l'addon)"] =
        "Unbekannter Charakter auf diesem Account: %s (einmal mit dem Addon einloggen)",
    ["regrouper tes rerolls (opt-in) : liste annoncée, commandes routées vers ton perso connecté"] =
        "Twinks gruppieren (Opt-in): Liste angekündigt, Aufträge zu deinem Online-Charakter geleitet",
    ["commande nommée pour %s : connecte ce perso, ou active /co alts on pour accepter d'ici."] =
        "Auftrag benannt für %s: logge diesen Charakter ein oder aktiviere /co alts on, um von hier anzunehmen.",
    ["|cFFFFCC00commande pour ton reroll %s|r de |cFFFFFFFF%s|r : %s%s%s"] =
        "|cFFFFCC00Auftrag für deinen Twink %s|r von |cFFFFFFFF%s|r: %s%s%s",
    ["En ligne via %s"] = "Online über %s",
    ["reroll : %s (%s)"] = "Twink: %s (%s)",
    -- v1.31.0
    ["Les cercles d'artisans, posés sur les communautés WoW"] =
        "Handwerkerkreise, auf WoW-Gemeinschaften aufgebaut",
    ["Le canal du royaume n'a ni mémoire ni liste de membres : qui n'était pas connecté quand tu as posté n'a rien vu, et chaque session recommence à chercher qui est là. Une communauté WoW répond aux deux. Marque-la avec /co circle et ses membres apparaissent sous « Cercle » dans l'onglet Artisans, avec leur présence, y compris ceux qui sont hors ligne. C'est toi qui crées la communauté et qui invites : un cercle est un petit groupe que tu as choisi, pas le royaume entier."] =
        "Der Realmkanal hat kein Gedächtnis und keine Mitgliederliste: Wer nicht eingeloggt war, als du gepostet hast, hat nichts gesehen, und jede Sitzung fängt wieder von vorn an. Eine WoW-Gemeinschaft löst beides. Markiere sie mit /co circle, und ihre Mitglieder erscheinen unter « Kreis » im Reiter Handwerker, mit ihrer Anwesenheit, auch die gerade offline sind. Du erstellst die Gemeinschaft und lädst ein, wen du willst: ein Kreis ist eine kleine Gruppe deiner Wahl, nicht der ganze Realm.",
    ["Rien n'est posté dans la communauté et rien n'en est lu. Ce qu'une communauté peut réellement porter a été mesuré avant qu'on s'appuie dessus, et c'est étroit : le texte d'un message de club est illisible depuis un addon, et un message addon envoyé sur son canal est accepté puis jeté. Le cercle te donne donc la liste et qui est en ligne ; les commandes et les niveaux de métier continuent de circuler exactement comme avant."] =
        "In die Gemeinschaft wird nichts gepostet und aus ihr nichts gelesen. Was eine Gemeinschaft wirklich tragen kann, wurde gemessen, bevor darauf gebaut wurde, und es ist wenig: der Text einer Klubnachricht ist von einem Addon aus nicht lesbar, und eine Addon-Nachricht an ihren Kanal wird angenommen und dann verworfen. Der Kreis liefert also die Liste und wer online ist; Aufträge und Berufsstufen laufen genau wie bisher.",
    ["Les métiers ne viennent pas non plus de la communauté : ces champs-là ne sont remplis que pour un roster de guilde. Un membre de cercle affiche ses métiers quand il répond à l'addon, comme tout le monde."] =
        "Die Berufe kommen ebenfalls nicht aus der Gemeinschaft: diese Felder werden nur für Gildenlisten gefüllt. Ein Kreismitglied zeigt seine Berufe, sobald es dem Addon antwortet, wie alle anderen auch.",
    -- v1.31.1
    ["Les nouveaux venus apparaissent tout seuls"] =
        "Neuzugänge tauchen von selbst auf",
    ["Quelqu'un qui venait d'installer l'addon restait invisible tant qu'il ne cliquait pas « Rafraîchir l'annuaire » — ce que personne ne pense à faire devant un annuaire qui a l'air vide, et avoir l'air vide était justement le problème."] =
        "Wer das Addon gerade erst installiert hatte, blieb unsichtbar, bis er auf « Verzeichnis aktualisieren » klickte — worauf niemand kommt, wenn das Verzeichnis leer aussieht, und genau das leere Aussehen war das Problem.",
    ["À la connexion, l'addon ne s'annonçait que sur le canal caché du royaume, le moins fiable de ses moyens d'atteindre les autres. L'annonce qui touche vraiment les inconnus n'a le droit de partir que juste après un clic ou une touche : à la connexion il n'y avait donc aucun moment pour l'envoyer, et elle était jetée au lieu d'être gardée. Elle attend maintenant, et part à ton premier clic ou ta première touche — quelques secondes, sans que tu fasses quoi que ce soit. La connexion sonde aussi directement les joueurs autour de toi, ce que le bouton « Rafraîchir » faisait déjà et pas elle."] =
        "Beim Anmelden kündigte dich das Addon nur im versteckten Realm-Kanal an, dem unzuverlässigsten seiner Wege, andere zu erreichen. Die Ankündigung, die Fremde wirklich erreicht, darf nur direkt nach einem Klick oder Tastendruck raus: beim Anmelden gab es also keinen Moment dafür, und sie wurde verworfen statt aufgehoben. Jetzt wartet sie und geht bei deinem ersten Klick oder Tastendruck raus — ein paar Sekunden, ohne dass du etwas tust. Beim Anmelden werden außerdem die Spieler um dich herum direkt angepingt, was der Aktualisieren-Knopf schon tat und das Anmelden nicht.",
    -- v1.32.0
    ["Forever lit enfin tes métiers et tes recettes"] =
        "Forever liest endlich deine Berufe und Rezepte",
    ["Sur WoW: Forever, l'addon ne voyait pas tes métiers : Forever tourne sur l'API du jeu moderne, et les fonctions qui lisaient tes compétences n'y existent pas. Rien ne plantait. L'annuaire t'annonçait simplement sans aucun métier, le clic droit disait que tu n'en avais pas, et « Mes artisans » restait vide. Tes recettes connues et leurs temps de recharge avaient le même problème. Tout est lu à la manière de Forever maintenant."] =
        "Auf WoW: Forever konnte das Addon deine Berufe nicht sehen. Forever läuft mit der API des modernen Spiels, und die Funktionen, die deine Fertigkeiten lasen, gibt es dort nicht. Es gab keinen Fehler. Das Verzeichnis kündigte dich einfach ohne Berufe an, der Rechtsklick behauptete, du hättest keine, und „Meine Handwerker“ blieb leer. Deine bekannten Rezepte und ihre Abklingzeiten hatten dasselbe Problem. Jetzt wird alles auf die Forever-Art gelesen.",
    ["Quand quelqu'un te cible dans l'onglet Commande, il voit ce que tu sais vraiment faire, plus une estimation. Et l'estimation elle-même était trop généreuse : une recette sans niveau connu comptait comme atteignable, si bien qu'un couturier niveau 13 se voyait proposer des pièces Stormcloth qui demandent le niveau 40. Un niveau inconnu veut dire « pas proposé » désormais."] =
        "Wenn dich jemand im Tab „Bestellen“ auswählt, sieht er, was du wirklich kannst, keine Schätzung mehr. Und die Schätzung war ohnehin zu großzügig: Ein Rezept ohne bekannte Stufe galt als erreichbar, sodass einem Schneider auf Stufe 13 Stormcloth-Teile angeboten wurden, die Stufe 40 verlangen. Unbekannt heißt jetzt: wird nicht angeboten.",
    ["La liste des recettes est celle de Forever : 2512 recettes tirées des pages Forever de Wowhead, au lieu des 1230 de vanilla. Forever a déplacé des choses, et les potions de soin sont maintenant en Secourisme, plus en Alchimie."] =
        "Die Rezeptliste ist die von Forever: 2512 Rezepte aus den Forever-Seiten von Wowhead statt der 1230 von Vanilla. Forever hat einiges verschoben, die Heiltränke stehen jetzt unter Erste Hilfe statt unter Alchemie.",
    ["Sur Forever, le clic droit sur le bouton de la minimap ouvre la fenêtre des métiers du jeu. Les métiers de tes rerolls se consultent désormais depuis « Mes artisans » (clic droit sur un métier). /co mute accepte les noms en prénom et nom, entre guillemets si l'addon n'a pas encore croisé le joueur."] =
        "Auf Forever öffnet ein Rechtsklick auf den Minimap-Button das Berufsfenster des Spiels. Die Berufe deiner Twinks findest du jetzt unter „Meine Handwerker“ (Rechtsklick auf einen Beruf). /co mute nimmt Vor- und Nachnamen an, in Anführungszeichen, wenn das Addon den Spieler noch nicht kennt.",
    -- v1.32.1
    ["La fenêtre de métier de Forever cesse de se plaindre"] =
        "Das Berufsfenster von Forever beschwert sich nicht mehr",
    ["Sur WoW: Forever, la colonne des commandes s'invite dans la fenêtre de métier du jeu. Elle y est l'hôte d'un cadre que le jeu protège, et presque tout ce qu'elle y faisait était refusé dès que tu étais en combat : ouvrir ou fermer la fenêtre pendant un combat déclenchait une volée d'erreurs « action bloquée », avec l'addon nommé au passage. La colonne ne touche plus au cadre pendant le combat, et reprend sa place à la fin."] =
        "Auf WoW: Forever sitzt die Auftragsspalte im Berufsfenster des Spiels. Sie ist dort Gast in einem geschützten Rahmen, und fast alles, was sie darin tat, wurde im Kampf verweigert. Das Fenster mitten im Kampf zu öffnen oder zu schließen warf eine Flut von Fehlern über blockierte Aktionen, mit dem Addon jedes Mal namentlich genannt. Im Kampf rührt die Spalte den Rahmen nicht mehr an und nimmt danach ihren Platz wieder ein.",
    ["Elle s'affiche aussi quand il faut. Il fallait deux passages : la fenêtre s'ouvre sur la page d'ensemble, où il n'y a aucun métier courant et donc rien à lister, si bien que la première visite semblait vide. Elle apparaît maintenant dès que tu es sur un métier, du premier coup."] =
        "Sie erscheint jetzt auch dann, wenn sie soll. Bisher brauchte es zwei Anläufe: Das Fenster öffnet auf der Übersichtsseite, wo es keinen aktuellen Beruf und also nichts aufzulisten gibt, weshalb der erste Besuch leer wirkte. Nun erscheint sie beim ersten Mal, sobald du auf einem Beruf bist.",
    ["Le reste : on ne peut plus la sortir de la fenêtre en la tirant, sa place appartient à son hôte ; les onglets de métier de Blizzard ne recouvrent plus son dernier onglet ; /co prof cuisine ouvre la Cuisine au lieu de la page d'ensemble ; et l'aide contextuelle n'entoure plus que ce qui est réellement affiché."] =
        "Der Rest: Sie lässt sich nicht mehr aus dem Fenster ziehen, ihr Platz gehört ihrem Gastgeber; die Berufsreiter von Blizzard verdecken ihren letzten Reiter nicht mehr; /co prof kochkunst öffnet die Kochkunst statt der Übersichtsseite; und die Hilfe umrahmt nur noch das, was wirklich zu sehen ist.",
    -- v1.32.2
    ["Tes barres d'action ne se bloquent plus en combat"] =
        "Deine Aktionsleisten werden im Kampf nicht mehr blockiert",
    ["Sur WoW: Forever, passer d'un onglet à l'autre dans la fenêtre de métier pendant un combat faisait refuser au jeu tout geste sur tes barres d'action, avec l'addon nommé à chaque fois. La fenêtre de métier n'y était pour rien. Deux petites pièces de l'addon l'étaient : ses menus déroulants et son aide « i » empruntaient des systèmes que le jeu partage avec sa propre interface, et s'en servir une seule fois suffisait à marquer cette interface à notre nom jusqu'au prochain rechargement. Les deux sont faits maison maintenant : même rendu, et le jeu n'a plus rien à redire."] =
        "Auf WoW: Forever hat ein Tabwechsel im Berufsfenster während eines Kampfes das Spiel dazu gebracht, jede Änderung an deinen Aktionsleisten zu verweigern, und jedes Mal wurde das Addon genannt. Am Berufsfenster lag es nicht. Schuld waren zwei kleine Teile des Addons: Seine Aufklappmenüs und seine Hilfe hinter dem i-Knopf nutzten Systeme, die das Spiel mit seiner eigenen Oberfläche teilt, und sie ein einziges Mal zu benutzen reichte, um diese Oberfläche bis zum nächsten Neuladen als unsere zu markieren. Beide sind jetzt Eigenbau: Sie sehen gleich aus, und das Spiel hat nichts mehr einzuwenden.",
    ["La colonne des commandes peut aussi se poser à côté de la fenêtre de métier plutôt que dedans : /co accole passe d'un mode à l'autre. Dedans reste le mode par défaut."] =
        "Die Auftragsspalte kann jetzt auch neben dem Berufsfenster stehen statt darin: /co accole wechselt zwischen beiden. Darin bleibt die Standardeinstellung.",
    ["Petites retouches : une longue liste de stats ne sort plus par le bas de l'écran, et chaque liste prend la largeur de sa plus longue entrée ; la liste des canaux de la fenêtre de partage des composants s'ouvre au-dessus d'elle et non plus dessous ; et l'aide suit la fenêtre si le jeu la déplace pendant qu'elle est ouverte."] =
        "Kleinere Korrekturen: Eine lange Werteliste läuft nicht mehr unten aus dem Bildschirm, und jede Liste ist so breit wie ihr längster Eintrag; die Kanalliste im Fenster zum Teilen der Reagenzien öffnet sich über diesem Fenster statt dahinter; und die Hilfe folgt dem Fenster, wenn das Spiel es verschiebt, während sie offen ist.",
    -- v1.33.0
    ["D'où vient une recette, sans MTSL"] = "Woher ein Rezept kommt, ohne MTSL",
    ["L'addon ne réclame plus MTSL. Sa base décrit Vanilla et TBC, or Forever a refait les tables d'objets dessous : 894 objets-recette qui n'existent que là, 173 disparus de Classic, et 24 identifiants communs qui désignent aujourd'hui un tout autre objet. Un annuaire périmé est pire qu'un annuaire absent, parce qu'il répond avec assurance. Les sources de recettes viennent maintenant de nos propres données, tirées des pages Forever de Wowhead."] =
        "Das Addon verlangt MTSL nicht mehr. Dessen Datenbank beschreibt Vanilla und TBC, doch Forever hat die Gegenstandstabellen darunter neu gebaut: 894 Rezeptgegenstände, die es nur dort gibt, 173 aus Classic, die verschwunden sind, und 24 gemeinsame IDs, die heute einen völlig anderen Gegenstand bezeichnen. Ein veraltetes Verzeichnis ist schlimmer als gar keines, weil es mit Überzeugung antwortet. Die Rezeptquellen stammen jetzt aus unseren eigenen Daten, erzeugt aus Wowheads Forever-Seiten.",
    ["Survole une recette que tu n'as pas apprise : elle te dit si le plan tombe en butin, s'il se vend ou s'il vient d'une quête, et elle nomme le PNJ et la zone quand elle les connaît. Sur Forever, le jeu le dit mieux que nous : sa formulation l'emporte dès qu'il en a une. Une recette de formateur est une déduction et non un fait, alors elle porte un « ? » plutôt que de faire semblant."] =
        "Fahre über ein Rezept, das du nicht gelernt hast: Es sagt dir, ob der Plan als Beute fällt, verkauft wird oder aus einer Quest stammt, und nennt NSC und Zone, wenn es sie kennt. Auf Forever sagt es das Spiel besser als wir, also gewinnt seine Formulierung, sobald es eine hat. Ein Lehrerrezept ist eine Schlussfolgerung und keine Tatsache, deshalb trägt es ein Fragezeichen, statt so zu tun als ob.",
    ["Le Plan de route remarche sur Forever, chiffré sur ton dernier scan Auctionator (Lazy Gold reste sur l'Era). Et la colonne des commandes change de contenu au lieu d'ouvrir des fenêtres par-dessus elle : trois onglets en haut, Commandes, Plan de route et Manquantes. Manquantes liste toutes les recettes que tu n'as pas apprises avec le rang qu'elles demandent, grisées tant que tu ne peux pas les prendre."] =
        "Die Aufstiegsroute funktioniert auf Forever wieder, berechnet aus deinem letzten Auctionator-Scan (Lazy Gold bleibt für Era). Und die Auftragsspalte wechselt ihren Inhalt, statt Fenster über sich zu öffnen: drei Reiter oben, Aufträge, Aufstiegsroute und Fehlende. Fehlende listet jedes Rezept, das du nicht gelernt hast, mit der nötigen Stufe, ausgegraut bis du es nehmen kannst.",
    ["Corrections : sur Forever la colonne comptait comme connues des recettes non apprises, et la route, les badges et ce que les autres artisans voyaient de toi reposaient là-dessus ; les prix sortaient vides ; la carte d'une commande sélectionnée était dessinée pour une fenêtre moitié plus large que la colonne, donc sa croix, son prix et le bord droit du panneau des composants étaient coupés ; une commande d'enchantement affichait « ? » au lieu de son nom."] =
        "Korrekturen: Auf Forever zählte die Spalte nicht gelernte Rezepte als gelernt, und Route, Abzeichen und das, was andere Handwerker von dir sahen, bauten darauf auf; Preise blieben leer; die Karte eines ausgewählten Auftrags war für ein Fenster gezeichnet, das deutlich breiter ist als die Spalte, sodass Schließkreuz, Preis und der rechte Rand der Komponentenliste abgeschnitten waren; ein Verzauberungsauftrag zeigte ein Fragezeichen statt seines Namens.",
    ["L'onglet Manquantes te dit enfin où aller"] =
        "Der Reiter „Fehlend\" sagt dir endlich, wohin",
    ["Survoler une recette que tu n'as pas te donnait son nom et son rang, c'est-à-dire ce que la ligne affichait déjà. Tu as maintenant l'infobulle de l'objet lui-même, puis ce qu'il te manque en points de métier, si la recette rapporte encore quelque chose à ton rang, et d'où vient le plan."] =
        "Ein Rezept, das du nicht kennst, zeigte dir beim Überfahren nur Namen und Rang, also genau das, was in der Zeile schon stand. Jetzt kommt zuerst der Gegenstands-Tooltip des Spiels, darunter wie viele Punkte dir fehlen, ob das Rezept auf deinem Rang noch einen Punkt bringt, und woher der Plan stammt.",
    ["Ce dernier point a beaucoup changé. L'addon connaissait un seul nom par plan et rien de son camp : « Recipe: Gingerbread Cookie » envoyait tout le monde chez Wulmort Jinglepocket, à Forgefer, Horde comprise. 1565 recettes nomment quelqu'un contre 337 avant, le marchand affiché est de ta faction, 719 donnent le prix réel du marchand sans aucun addon de prix, et 846 PNJ ont des coordonnées : un clic pose un repère, ce qui ne marchait plus depuis MTSL."] =
        "Genau dieser letzte Teil ist deutlich besser geworden. Das Addon kannte einen Namen pro Plan und nichts über dessen Fraktion, also schickte „Recipe: Gingerbread Cookie\" alle zu Wulmort Jinglepocket nach Eisenschmiede, Horde inklusive. 1565 Rezepte nennen jetzt jemanden statt 337, der gezeigte Händler gehört zu deiner Fraktion, 719 nennen den echten Händlerpreis ganz ohne Preis-Addon, und 846 NSCs haben Koordinaten: ein Klick setzt einen Wegpunkt, was seit MTSL nicht mehr ging.",
    ["Les formateurs. Aucune page ne dit « ça s'apprend au formateur » : l'addon le déduisait de l'absence d'objet-recette et affichait un point d'interrogation, sur 788 recettes. Wowhead le publie en fait sur la page du sort et pas celle de l'objet, ce qui en a nommé 398. Et quand tu parles à un formateur de métier, l'addon note ce qu'il enseigne et où il se tient : le point d'interrogation disparaît et tu récupères ses coordonnées. Si ta fenêtre de formateur filtre ce qu'elle affiche, il te le dit au lieu de n'en moissonner qu'un tiers en silence."] =
        "Und die Lehrer. Keine Seite sagt „das lernt man beim Lehrer\": das Addon schloss es aus dem Fehlen eines Rezeptgegenstands und zeigte ein Fragezeichen, bei 788 Rezepten. Wowhead verrät es doch, auf der Zauber- statt der Gegenstandsseite, was 398 davon einen Namen gab. Und wenn du mit einem Berufslehrer sprichst, notiert das Addon, was er lehrt und wo er steht: das Fragezeichen verschwindet und du bekommst seine Koordinaten. Filtert dein Lehrerfenster, sagt es dir das, statt still nur ein Drittel mitzunehmen.",
    ["Corrigé : un plantage en donjon (le client rend des valeurs « secrètes » pour certaines données d'unité, et l'une d'elles finissait en clé de table trois appels plus loin, dans une fonction d'annuaire qui n'avait aucune raison de se méfier d'un nom), et le changement d'onglet de métier qui laissait la liste d'un métier avec les infobulles d'un autre."] =
        "Behoben: ein Absturz in Dungeons (der Client liefert für manche Einheitendaten „geheime\" Werte zurück, und einer landete drei Aufrufe später als Tabellenschlüssel in einer Verzeichnisfunktion, die keinen Grund hatte, einem Namen zu misstrauen), und der Wechsel des Berufsreiters, der die Liste eines Berufs mit den Tooltips eines anderen stehen ließ.",
    -- v1.35.1
    ["Un niveau qu'on ne connaît pas n'est pas un niveau 0"] =
        "Eine Fertigkeitsstufe, die wir nicht kennen, ist keine Null",
    ["La vue Manquantes plaçait huit recettes de Couture en tête de liste en te disant qu'elles étaient à ta portée, affichées « niveau requis 0 ». 29 recettes réparties sur six métiers n'ont aucun niveau dans les données, et l'addon lisait cette absence comme un zéro — qui se classe en tête et passe tous les tests de « peux-tu l'apprendre »."] =
        "Die Ansicht Fehlende setzte acht Schneiderei-Rezepte an den Anfang der Liste und erklärte sie für erreichbar, alle mit „benötigter Skill 0“. 29 Rezepte aus sechs Berufen haben in den Daten überhaupt keine Stufe, und das AddOn las diese Abwesenheit als Null — die sortiert zuerst und besteht jede Prüfung „kannst du das schon lernen“.",
    ["Elles affichent « ? » maintenant, elles descendent en fin de liste, et l'addon ne les dit ni à ta portée ni hors de portée, puisqu'il l'ignore. L'infobulle le dit franchement. Les niveaux eux-mêmes manquent toujours : c'est un travail de données, pas d'affichage."] =
        "Jetzt zeigen sie ein „?“, sie rutschen ans Ende der Liste, und das AddOn behauptet weder, dass sie erreichbar sind, noch dass sie es nicht sind, denn es weiß es nicht. Der Tooltip sagt es. Die Stufen selbst fehlen weiterhin: das ist Datenarbeit, keine Anzeigefrage.",
    -- v1.35.0
    ["Enchanter la pièce d'un autre, depuis l'échange"] =
        "Fremde Ausrüstung verzaubern, direkt im Handelsfenster",
    ["Le panneau flottant d'enchantement a disparu : sur Forever, la fenêtre de métier se dessinait exactement par-dessus. Son rôle revient à la colonne de métier, qui passe en mode Échange dès qu'un échange s'ouvre avec ton Enchantement affiché — la silhouette du partenaire, la pièce qu'il a posée dans l'emplacement « ne sera pas échangé », et ce que ses composants désignent."] =
        "Das schwebende Verzauberungsfenster ist weg: Auf Forever wurde das Berufsfenster genau darüber gezeichnet. Seine Aufgabe übernimmt jetzt die Berufsspalte, die in den Handelsmodus wechselt, sobald ein Handel mit geöffneter Verzauberkunst beginnt — dein Partner, das Teil in dem Platz, der nicht gehandelt wird, und worauf seine Materialien hindeuten.",
    ["Clique un emplacement de la silhouette : il reçoit la demande de poser cette pièce (chuchotement, plus une invite d'un clic s'il a l'addon), et la liste de recettes de Blizzard se filtre sur cet emplacement. La main droite coche « Arme » et « Arme à deux mains » à la fois, faute de savoir ce qu'il tient."] =
        "Klicke auf einen Platz der Silhouette: Er wird um dieses Teil gebeten (Flüstern, dazu eine Abfrage mit einem Klick, wenn er das AddOn hat), und Blizzards eigene Rezeptliste filtert auf diesen Platz. Die Waffenhand hakt „Waffe“ und „Zweihandwaffe“ zugleich an, denn noch weiß das AddOn nicht, was er trägt.",
    ["Dès qu'une pièce est posée, la liste suit la pièce elle-même plutôt que ta demande. À la fin de l'échange elle retrouve tes filtres d'avant, y compris celui que tu avais posé toi-même, et la colonne revient sur l'onglet que tu regardais."] =
        "Liegt etwas auf dem Tisch, folgt die Liste dem Gegenstand selbst statt deiner Anfrage. Am Ende des Handels kehren deine vorherigen Filter zurück, auch der, den du selbst gesetzt hattest, und die Spalte kehrt zu deinem Reiter zurück.",
    ["S'il pose aussi des composants, la colonne nomme l'enchantement qu'ils désignent — elle lit ce qu'il pose, jamais tes sacs, et se tait quand plusieurs enchantements collent. Et si un échange s'ouvre alors que ton Enchantement est fermé, un onglet apparaît au bord droit de la fenêtre d'échange pour l'ouvrir."] =
        "Legt er auch Materialien dazu, nennt die Spalte die Verzauberung, auf die sie hindeuten. Sie liest, was er hinlegt, nie deine Taschen, und schweigt, wenn mehrere Verzauberungen passen. Und öffnet sich ein Handel bei geschlossener Verzauberkunst, erscheint am rechten Rand des Handelsfensters ein Reiter, der sie öffnet.",
    -- v1.34.1
    ["Plus d'erreur en entrant en ville"] =
        "Kein Fehler mehr beim Betreten einer Stadt",
    ["Avec la détection des artisans sans l'addon activée (/co crafters on), chaque entrée en ville déclenchait une erreur « action interdite » au nom de l'addon. Sur Forever, le jeu n'autorise plus les addons à écouter le journal de combat, et l'addon s'y abonnait quand même. C'est fini : la détection passe désormais par les messages de fabrication du chat (« Untel crée … »), qui restent ouverts aux addons."] =
        "Mit aktivierter Handwerker-Erkennung (/co crafters on) löste jedes Betreten einer Stadt einen Fehler „Aktion verboten“ mit dem Namen des Addons aus. Auf Forever dürfen Addons das Kampflog nicht mehr abhören, und das Addon hat es trotzdem versucht. Das ist vorbei: Die Erkennung läuft jetzt über die Herstellungsmeldungen im Chat („X stellt Y her“), die Addons weiterhin lesen dürfen.",
    ["Le panneau d'enchantement qui s'ouvre à côté de la fenêtre d'échange disait toujours « Ouvre ta fenêtre d'Enchantement », même ouverte : il cherchait une fenêtre qui n'existe pas sur Forever. Il liste maintenant tes enchantements pour la pièce posée, classés comme avant, et il remarque quand tu ouvres l'Enchantement en plein échange. Cliquer une ligne ne lance pas encore l'enchantement."] =
        "Das Verzauberungsfenster neben dem Handelsfenster verlangte immer „Öffne dein Verzauberungsfenster“, selbst wenn es offen war: Es suchte ein Fenster, das es auf Forever nicht gibt. Jetzt listet es deine Verzauberungen für das hingelegte Teil auf, sortiert wie bisher, und bemerkt, wenn du die Verzauberkunst mitten im Handel öffnest. Ein Klick auf eine Zeile wirkt die Verzauberung noch nicht.",
    ["Sous le capot : l'addon ne transporte plus rien du code de Classic Era (cette version reste figée en 1.30.0), et il lit ton journal de quêtes directement dans le jeu, sans passer par les copies des anciennes fonctions que Questie installe quand il est présent."] =
        "Unter der Haube: Das Addon enthält keinen Code von Classic Era mehr (diese Version bleibt bei 1.30.0 eingefroren) und liest dein Questlog direkt aus dem Spiel, statt über die Ersatzfunktionen zu gehen, die Questie installiert, wenn es vorhanden ist.",

    -- v1.36.0
    ["Ce qui rapporte, et dire au royaume que tu es dispo"] =
        "Was sich lohnt, und dem Realm sagen, dass du frei bist",
    ["La colonne de métier gagne un onglet, Profit : ce que tu sais faire qui vaut la peine d'être fait, la plus grosse marge en haut, avec le prix de vente face au coût des composants. Un clic sur une ligne amène la recette dans la liste de Blizzard. L'onglet n'apparaît que si Auctionator tourne, puisque les prix viennent de lui, et il le dit au lieu de t'afficher un zéro."] =
        "Die Berufsspalte hat einen neuen Reiter, Profit. Er listet auf, was zu fertigen sich lohnt, groesste Marge zuerst, mit dem Verkaufspreis gegen die Kosten der Reagenzien. Ein Klick auf eine Zeile springt in Blizzards eigener Liste zu diesem Rezept. Der Reiter erscheint nur, wenn Auctionator laeuft, denn von dort kommen die Preise, und er sagt es, statt dir eine Null zu zeigen.",
    ["« Chercher du travail » est revenu. Sur Forever le bouton avait disparu avec l'ancienne fenêtre à trois colonnes : il ne restait que /co lfw, et plus aucun moyen de régler ton offre. C'est maintenant une bande en bas de la colonne, qui affiche « Dispo — Forge » dans toutes les vues. Oublier qu'on est annoncé est exactement ce que le minuteur d'expiration existe pour rattraper."] =
        "'Arbeit suchen' ist zurueck. Auf Forever war der Knopf mit dem alten Dreispaltenfenster verschwunden, uebrig blieb nur /co lfw und keinerlei Moeglichkeit, dein Angebot zu aendern. Jetzt ist es ein Streifen am unteren Rand der Spalte, der in jeder Ansicht 'Verfuegbar, Schmiedekunst' anzeigt. Zu vergessen, dass man inseriert ist, ist genau der Grund, warum der Eintrag von selbst ablaeuft.",
    ["À côté, le bouton Offre ouvre ce que tu proposes : les composants de base, une commission par craft, ne prendre que ce qui te fait progresser, les réactifs que tu fournis. Nouveau, tu coches aussi les recettes précises que tu proposes, et qui te consulte les voit par leur nom. La liste des réactifs se limite désormais à ce que tu sais crafter — un travailleur du cuir à 82 ne se voit plus proposer de la Vigne de sang."] =
        "Daneben oeffnet ein Angebot-Knopf, wozu du bereit bist. Die Haendlerreagenzien stellen, eine feste Gebuehr pro Fertigung, nur Arbeit annehmen, die dich Fertigkeit bringt, welche Reagenzien du mitbringst. Neu ist, dass du die konkreten Rezepte ankreuzt, die du anbietest, und wer dich nachschlaegt, sieht sie beim Namen. Die Reagenzienliste zeigt nur noch, was du wirklich fertigen kannst, ein Lederer auf 82 bekommt also kein Blutrebe mehr angeboten.",
    ["Recharge ton interface et tu revois les annonces des autres en quelques secondes. Avant, personne ne se ré-annonçait à ton arrivée : tu pouvais rester devant un radar vide pendant huit minutes sans le savoir."] =
        "Lade deine Oberflaeche neu, und die Eintraege der anderen sind binnen Sekunden wieder da. Zuvor hat sich bei deiner Ankunft niemand erneut gemeldet, du konntest also acht Minuten vor einem leeren Radar sitzen, ohne es zu merken.",
    ["Plus petit. Le bouton d'aide « i » se posait sur la dernière languette et lui volait ses clics. L'onglet « Plan de route » s'appelle « Route », ce qui a fait la place au reste. Et l'addon relève le niveau qu'un formateur exige, donc les recettes affichées « ? » se remplissent à mesure que tu passes les voir."] =
        "Kleineres. Der Hilfeknopf 'i' sass auf dem letzten Reiter und schluckte dessen Klicks. Der Reiter 'Levelroute' heisst jetzt 'Route', was den Platz fuer den Rest geschaffen hat. Und das Addon liest die Fertigkeitsstufe, die ein Lehrer verlangt, sodass Rezepte mit '?' sich fuellen, waehrend du sie besuchst.",

    -- v1.36.1
    ["Une icône dans la liste des addons"] =
        "Ein Symbol in der Addon-Liste",
    ["L'addon a enfin sa propre icône dans la liste des addons, à la place du point d'interrogation. Rien d'autre ne change."] =
        "Das Addon hat endlich ein eigenes Symbol in der Addon-Liste statt des Fragezeichens. Sonst ändert sich nichts.",
    -- v1.36.2
    ["Les commandes trouvent leur destinataire"] =
        "Aufträge erreichen den richtigen Empfänger",
    ["Sur WoW Forever, chaque personnage a un nom de famille, et le jeu te désigne partout par « Prénom Nom ». L'addon t'appelait par ton prénom seul et ne se reconnaissait plus : une commande à ton nom arrivait puis était ignorée, une commande postée sur le canal était rejetée comme si quelqu'un postait à la place d'un autre, et tu pouvais te retrouver dans ta propre liste d'artisans. C'est réparé, y compris pour les commandes des joueurs restés en 1.36.1."] =
        "In WoW Forever hat jeder Charakter einen Nachnamen, und das Spiel nennt dich überall 'Vorname Nachname'. Das Addon benutzte nur deinen Vornamen und erkannte sich selbst nicht mehr: Ein Auftrag an dich kam an und wurde ignoriert, ein im Kanal geposteter Auftrag wurde verworfen, als würde jemand im Namen eines anderen posten, und du konntest in deiner eigenen Handwerkerliste auftauchen. Behoben, auch für Aufträge von Spielern, die noch 1.36.1 nutzen.",
    ["Une ligne du canal Commerce comme « dont need fire wand: [Lesser Magic Wand] » n'est plus prise pour une demande."] =
        "Eine Handelszeile wie 'dont need fire wand: [Lesser Magic Wand]' gilt nicht mehr als Anfrage.",
    -- v1.39.1
    ["Les commandes envoyées par courrier se terminent seules"] =
        "Verschickte Aufträge schließen sich selbst ab",
    ["Quand un artisan t'envoie ta commande par courrier, prendre l'objet dans ta boîte aux lettres la marque reçue, comme quand tu le ramasses. L'artisan est crédité tout de suite. Avant, elle restait « Remise » et il fallait cliquer « J'ai reçu » dans le Carnet."] =
        "Schickt dir ein Handwerker deinen Auftrag per Post, gilt er als erhalten, sobald du den Gegenstand aus dem Briefkasten nimmst, wie beim Plündern. Der Handwerker wird sofort gutgeschrieben. Bisher blieb er auf 'Geliefert' und du musstest im Auftragsbuch 'Erhalten' klicken.",
    ["Côté artisan, « Remplir depuis commande » pouvait joindre une pile entière à une commande plus petite : une commande de 1 partait avec 9. Il coupe maintenant la bonne quantité dans tes sacs et ne joint qu'elle ; sans case libre pour la coupe, le chat te dit combien séparer toi-même."] =
        "Auf Handwerkerseite konnte 'Aus Auftrag füllen' einen ganzen Stapel an einen kleineren Auftrag hängen: Ein Auftrag über 1 ging mit 9 raus. Jetzt wird die richtige Menge in deinen Taschen abgetrennt und nur sie angehängt; ohne freien Taschenplatz sagt dir der Chat, wie viele du selbst abtrennen musst.",
    -- v1.39.0
    ["La fenêtre prend l'allure du jeu"] =
        "Das Fenster sieht aus wie das Spiel",
    ["Les onglets de la fenêtre passent sur son bord droit, en icônes, comme dans la fenêtre de métier. Survole-les pour lire leur nom ; le titre dit où tu es, et l'icône du Carnet compte tes commandes en cours."] =
        "Die Tabs des Fensters sitzen jetzt als Symbole am rechten Rand, wie im Berufsfenster. Fahre darüber, um ihren Namen zu lesen; der Titel zeigt, wo du bist, und das Symbol des Auftragsbuchs zählt deine offenen Aufträge.",
    ["Toutes les listes et les pages défilent avec la barre fine du jeu, qui se cache quand tout tient : ressources de Récolte, Carnet, Aide, Nouveautés, et les vues Commandes, Route, Manquantes et Profit de la fenêtre de métier. Chaque bloc est posé dans un encart, comme dans la fenêtre de métier."] =
        "Alle Listen und Seiten scrollen mit der schmalen Bildlaufleiste des Spiels, die sich versteckt, wenn alles passt: Ressourcen in Sammeln, Auftragsbuch, Hilfe, Neues sowie die Ansichten Aufträge, Route, Fehlend und Gewinn im Berufsfenster. Jeder Block sitzt in einem Einsatz, wie im Berufsfenster.",
    ["Dans Commande, la commission est la case or, argent, cuivre du jeu, et la quantité a des flèches. Le Carnet se trie : clique l'en-tête d'une colonne, reclique pour inverser. Le Journal et la fiche « Poster en quête » prennent le cadre du journal de quêtes du jeu, livre et parchemin."] =
        "In Auftrag ist die Provision das Gold-, Silber- und Kupferfeld des Spiels, und die Menge hat Pfeile. Das Auftragsbuch lässt sich sortieren: Klicke auf einen Spaltenkopf, erneut zum Umkehren. Das Journal und das Blatt 'Als Quest erstellen' nutzen den Rahmen des Questlogs, mit Buch und Pergament.",
    ["Les panneaux de l'échange et du courrier prennent l'allure de ces fenêtres. Le courrier ne liste plus que ce qui se poste : un enchantement se fait à l'échange, où l'onglet Enchantement brille quand une commande d'enchant acceptée te lie à ton partenaire. L'Aide est réécrite, et ses flèches affichées en carrés sont réparées."] =
        "Die Panels an Handel und Post passen jetzt zu diesen Fenstern. Die Post listet nur noch, was sich verschicken lässt: Eine Verzauberung geschieht im Handel, wo der Verzauberkunst-Tab leuchtet, wenn dich ein angenommener Verzauberungsauftrag mit deinem Partner verbindet. Die Hilfe ist neu geschrieben, ihre als Quadrate angezeigten Pfeile sind repariert.",
    -- v1.38.0
    ["Un signe quand une mise à jour est là"] =
        "Ein Zeichen, wenn ein Update da ist",
    ["Quand le réseau signale une nouvelle version, le logo de Crafting Order apparaît en haut de la minicarte, là où Blizzard pose la lettre du courrier. Survole-le pour voir quelle version est sortie et laquelle tu as, clique pour le détail dans le chat. Il disparaît une fois la mise à jour faite."] =
        "Meldet das Netzwerk eine neuere Version, erscheint das Crafting-Order-Logo oben an der Minikarte, dort wo Blizzard den Postbrief anzeigt. Fahre darüber, um zu sehen, welche Version erschienen ist und welche du hast; ein Klick zeigt die Details im Chat. Es verschwindet, sobald du aktualisiert hast.",
    -- v1.37.0
    ["Les artisans se retrouvent dans une communauté"] =
        "Handwerker treffen sich in einer Gemeinschaft",
    ["Sur WoW Forever, le canal caché de l'addon, CraftLinkNet, est découpé en salles : deux joueurs côte à côte pouvaient ne jamais voir leurs commandes. L'addon ne l'utilise plus, et le quitte si tu y es encore. Les artisans se retrouvent dans la communauté « Crafting Order PVE », une par camp."] =
        "Auf WoW Forever wird der versteckte Kanal des Addons, CraftLinkNet, in getrennte Räume aufgeteilt: Zwei Spieler nebeneinander sahen womöglich nie ihre Aufträge. Das Addon nutzt ihn nicht mehr und verlässt ihn, falls du noch drin bist. Handwerker treffen sich jetzt in der Gemeinschaft 'Crafting Order PVE', eine pro Fraktion.",
    ["Sans cercle d'artisans, tu reçois à la connexion un whisper de toi-même avec un lien Rejoindre. Clique dessus, puis Rejoindre dans la fenêtre qui s'ouvre : l'addon en fait ton cercle tout seul. « /co circle nolink » coupe ce rappel."] =
        "Ohne Handwerkerkreis bekommst du beim Einloggen ein Flüstern von dir selbst mit einem Beitreten-Link. Klicke darauf, dann auf Beitreten im Fenster, das sich öffnet: Das Addon macht sie von selbst zu deinem Kreis. '/co circle nolink' schaltet diese Erinnerung ab.",
    ["Tout ce qui passait par le canal part en whisper aux joueurs de l'addon en ligne : ton profil, les commandes et leurs annulations, la recherche de travail. Les joueurs restés en 1.36 ne te joignent plus que par les amis, la guilde, un cercle commun ou une commande à leur nom : dis-leur de mettre à jour."] =
        "Alles, was über den Kanal lief, geht jetzt per Flüstern an Addon-Nutzer, die online sind: dein Profil, Aufträge und ihre Stornierungen, die Arbeitssuche. Spieler, die noch 1.36 nutzen, erreichen dich nur noch über Freunde, Gilde, einen gemeinsamen Kreis oder einen Auftrag auf ihren Namen: Sag ihnen, sie sollen aktualisieren.",
    ["L'onglet Artisans a une ligne par communauté, à son nom, et un joueur passe hors ligne dès que la communauté le dit parti. La ligne Confédération n'apparaît que si GreenWall tourne."] =
        "Der Reiter Handwerker hat eine Zeile pro Gemeinschaft, mit ihrem Namen, und ein Spieler wird offline angezeigt, sobald die Gemeinschaft meldet, dass er weg ist. Die Zeile Konföderation erscheint nur, wenn GreenWall läuft.",
    ["Aussi : les listes de Commande, Récolte, Artisans et Mes artisans défilent comme celle des métiers de Blizzard ; un artisan choisi depuis Artisans arrive sélectionné dans Commande ; le bouton d'aide passe au-dessus du portrait et ne se cache plus derrière la Route ; Manquantes n'affiche plus l'exemplaire de l'autre camp d'une recette jumelle ; la Route puise dans tes sacs avant l'hôtel des ventes ; ouvrir le lien de métier d'un autre joueur ne range plus ses recettes dans les tiennes."] =
        "Außerdem: Die Listen in Auftrag, Sammeln, Handwerker und Meine Handwerker scrollen wie Blizzards Berufsliste; ein aus Handwerker gewählter Handwerker ist in Auftrag vorausgewählt; der Hilfeknopf sitzt über dem Porträt und versteckt sich nicht mehr hinter der Route; Fehlende zeigt nicht mehr das Exemplar der anderen Fraktion eines Zwillingsrezepts; die Route nutzt erst deine Taschen, dann das Auktionshaus; der Berufslink eines anderen Spielers legt seine Rezepte nicht mehr unter deinen ab.",
    -- v1.40.0
    ["Tes commandes sur Commerce, et l'addon sans communauté"] =
        "Deine Aufträge im Handel, und das Addon ohne Gemeinschaft",
    ["Coche « Annoncer en Commerce » en postant une commande à tous : l'addon écrit aussi une ligne sur Trade (Services), dans une capitale, que tout le monde lit. Les joueurs de l'addon, même inconnus, reçoivent la vraie commande en quelques secondes ; les autres peuvent te chuchoter. Clic droit sur la commande dans le Carnet pour la rappeler, une fois par quart d'heure."] =
        "Kreuze „Im Handelskanal ankündigen“ an, wenn du einen Auftrag an alle postest: Das Addon schreibt zusätzlich eine Zeile in Handel (Dienstleistungen), in einer Hauptstadt, die alle lesen können. Addon-Nutzer, auch unbekannte, erhalten den echten Auftrag in wenigen Sekunden; alle anderen können dir flüstern. Rechtsklick auf den Auftrag im Auftragsbuch wiederholt ihn, einmal pro Viertelstunde.",
    ["La même case, dans l'offre de « Chercher du travail », annonce ta dispo : une ligne « LFW » sur Trade (Services) quand tu l'actives, et les joueurs de l'addon reçoivent ton profil."] =
        "Dasselbe Kästchen im Angebot von „Arbeit suchen“ kündigt deine Verfügbarkeit an: eine „LFW“-Zeile in Handel (Dienstleistungen), wenn du sie einschaltest, und Addon-Nutzer erhalten dein Profil.",
    ["L'addon marche sans la communauté Crafting Order PVE et ne t'en envoie plus le lien. Les artisans se trouvent par les amis, la guilde, tes cercles, les annonces sur Commerce et la salle de découverte, où les joueurs de l'addon se disent bonjour (« /co channel room off » pour la quitter)."] =
        "Das Addon funktioniert ohne die Gemeinschaft Crafting Order PVE und schickt dir ihren Link nicht mehr. Handwerker finden sich über Freunde, Gilde, deine Kreise, die Ankündigungen im Handel und den Entdeckungsraum, in dem sich Addon-Nutzer begrüßen („/co channel room off“ zum Verlassen).",
    ["Aussi : l'addon ne crie plus de ping, que Forever refusait sans rien dire ; « /co note » prépare le texte de tes métiers à coller dans ta note de membre d'une communauté, et l'onglet Artisans affiche la note des autres."] =
        "Außerdem: Das Addon schreit keinen Ping mehr, den Forever stillschweigend ablehnte; „/co note“ bereitet den Text deiner Berufe vor, den du in deine Mitgliedsnotiz einer Gemeinschaft einfügst, und der Reiter Handwerker zeigt die Notizen der anderen.",
}

for k, v in pairs(news) do L[k] = v end
